    },
    {
      "scene_number": 16,
      "caption": "The scout pulls the lever, and the drawbridge begins to lower.",
      "visual_description": "Two-handed pull on a brass lever; gears grind and chains rattle as the bridge descends over a dark moat.",
      "characters": ["scout", "sleepy_official", "map_reader", "mage", "griffin"]
    },
    {
      "scene_number": 17,
      "caption": "The team races across the bridge as patrols close in.",
      "visual_description": "Running figures on the stone bridge, torches and arrows behind them; the griffin flies overhead, scattering pursuing soldiers.",
      "characters": ["map_reader", "scout", "mage", "sleepy_official", "griffin", "armored_patrol"]
    },
    {
      "scene_number": 18,
      "caption": "They escape into the misty forest beyond the bridge.",
      "visual_description": "The ruined city recedes through a veil of fog; the griffin lands on a mossy arch as the team catches their breath.",
      "characters": ["map_reader", "scout", "mage", "sleepy_official", "griffin"]
    }
  ]
}
